// Turns each Yahoo chart response into one flat row (matches market_prices columns).
const syms = $('Build Symbols').all().map(i => i.json);
const responses = $input.all();
const out = [];
let haveIndex = false;

responses.forEach((it, idx) => {
  const s = syms[idx];
  if (!s) return;
  const r = it.json?.chart?.result?.[0];
  if (!r || !Array.isArray(r.timestamp)) return; // failed / unknown symbol

  const q = r.indicators?.quote?.[0] || {};
  const meta = r.meta || {};
  const bars = r.timestamp
    .map((t, i) => ({ t, c: q.close?.[i], v: q.volume?.[i] }))
    .filter(b => b.c != null);
  const pct = (a, b) => (a != null && b) ? +(((a / b) - 1) * 100).toFixed(3) : null;
  const offset = meta.gmtoffset ?? 0;
  const dateOf = (t) => new Date((t + offset) * 1000).toISOString().slice(0, 10);

  let close, prev_close, change_pct, ret_5d = null, ret_20d = null, vol_ratio_20d = null, volume, trade_date;

  if (bars.length >= 2) {
    // Normal case: enough daily history to compute everything.
    const last = bars[bars.length - 1];
    const prev = bars[bars.length - 2];
    const back = (n) => bars[bars.length - 1 - n]?.c;
    const vols = bars.slice(-21, -1).map(b => b.v).filter(v => v > 0);
    const avgVol = vols.length ? vols.reduce((a, b) => a + b, 0) / vols.length : null;
    close = last.c; prev_close = prev.c;
    change_pct = pct(last.c, prev.c);
    ret_5d = pct(last.c, back(5));
    ret_20d = pct(last.c, back(20));
    volume = last.v;
    vol_ratio_20d = (avgVol && last.v) ? +(last.v / avgVol).toFixed(3) : null;
    trade_date = dateOf(last.t);
  } else {
    // Sparse history (Yahoo sometimes returns a single bar for PSE symbols): use the quote fields in meta.
    // Deliberately NOT using chartPreviousClose: it is the close before the *range start*, not yesterday's.
    close = meta.regularMarketPrice ?? bars[0]?.c;
    if (close == null) return;
    prev_close = meta.previousClose ?? (meta.fulldayChange != null ? close - meta.fulldayChange : null);
    change_pct = meta.regularMarketChangePercent ?? meta.fulldayChangePercent ?? pct(close, prev_close);
    volume = meta.regularMarketVolume ?? bars[0]?.v;
    const t = bars[0]?.t ?? meta.regularMarketTime;
    if (t == null) return;
    trade_date = dateOf(t);
  }

  if (s.kind === 'index') {           // PSEi may come from PSEI.PS or ^PSEI: keep the first that worked
    if (haveIndex) return;
    haveIndex = true;
  }

  out.push({ json: {
    trade_date,
    symbol: s.kind === 'index' ? 'PSEI.PS' : s.symbol,   // canonical key in Supabase
    name: s.name,
    kind: s.kind,
    close: +Number(close).toFixed(4),
    prev_close: prev_close != null ? +Number(prev_close).toFixed(4) : null,
    change_pct: change_pct != null ? +Number(change_pct).toFixed(3) : null,
    ret_5d,
    ret_20d,
    volume: volume ? Math.round(volume) : null,
    vol_ratio_20d,
  }});
});

return out;

// Collects prices + news, decides whether PSE traded today, and builds the Gemini request body.
const cfg = $('Config').first().json;
const maxAgeMs = (Number(cfg.news_max_age_hours) || 30) * 3600 * 1000;

const prices = $('Parse Market Data').all().map(i => i.json);
const psei = prices.find(p => p.kind === 'index');
const today = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10); // Manila date
// Config.force_run = true lets you test on weekends/holidays using the latest session's data.
const force = String(cfg.force_run).toLowerCase() === 'true';
const is_trading_day = !!psei && (force || psei.trade_date === today);
const skip_reason = !psei
  ? 'no PSEi price data came back from Yahoo (open Fetch Yahoo Prices / Parse Market Data to see why)'
  : `latest PSEi bar is ${psei.trade_date}, not today (${today}): market holiday or delayed data`;

// ---- News ----
const SOURCES = [
  ['RSS BusinessWorld', 'BusinessWorld'],
  ['RSS Philstar Business', 'Philstar'],
  ['RSS Google News PSEi', 'Google News'],
];
const strip = (s) => String(s || '')
  .replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

const seen = new Set();
let news = [];
for (const [node, label] of SOURCES) {
  let items = [];
  try { items = $(node).all(); } catch (e) { continue; }
  let count = 0;
  for (const it of items) {
    const j = it.json || {};
    if (j.error || !j.title || !j.link) continue;
    const published = j.isoDate || j.pubDate;
    const ts = published ? Date.parse(published) : NaN;
    if (!isNaN(ts) && Date.now() - ts > maxAgeMs) continue;
    const key = strip(j.title).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    news.push({
      source: label,
      title: strip(j.title),
      url: j.link,
      published_at: isNaN(ts) ? null : new Date(ts).toISOString(),
      snippet: strip(j.contentSnippet || j.content || j.summary || '').slice(0, 280),
    });
    if (++count >= 12) break;
  }
}
news.sort((a, b) => (b.published_at || '').localeCompare(a.published_at || ''));
news = news.slice(0, 30).map((n, i) => ({ id: i + 1, ...n }));

// ---- Prompt ----
const fmt = (n, d = 2) => n == null ? 'n/a' : Number(n).toLocaleString('en-US', { maximumFractionDigits: d });
const pct = (n) => n == null ? 'n/a' : `${n > 0 ? '+' : ''}${Number(n).toFixed(2)}%`;

const priceLines = prices.map(p =>
  `${p.kind.toUpperCase()} | ${p.symbol} | ${p.name} | close ${fmt(p.close, 4)} | 1d ${pct(p.change_pct)} | 5d ${pct(p.ret_5d)} | 20d ${pct(p.ret_20d)} | volume vs 20d avg x${p.vol_ratio_20d ?? 'n/a'} | as of ${p.trade_date}`
).join('\n');

const newsLines = news.length
  ? news.map(n => `[${n.id}] (${n.source}, ${n.published_at || 'n/a'}) ${n.title}${n.snippet ? ' — ' + n.snippet : ''}`).join('\n')
  : '(no recent news items were retrieved)';

const system = [
  'You are a market-analysis assistant writing an end-of-day brief on the Philippine Stock Exchange (PSE).',
  'Use ONLY the price data and news items provided. Never invent numbers, prices, tickers, events, or URLs.',
  'If evidence is thin or conflicting, say so and keep sentiment near neutral.',
  'Sentiment means likely near-term impact on Philippine equities (PSEi). Scores range from -1 (very bearish/negative) to +1 (very bullish/positive).',
  'Respond with a single JSON object and nothing else.',
].join(' ');

const user = `Session date (Asia/Manila): ${psei?.trade_date || today}

PRICE DATA (Yahoo Finance daily bars):
${priceLines}

NEWS (last ${cfg.news_max_age_hours || 30}h, numbered):
${newsLines}

Return JSON with exactly this shape:
{
  "market_sentiment": { "label": "bullish|neutral|bearish", "score": number, "rationale": "1-2 sentences" },
  "summary": "2-3 sentence plain-English recap of the session and key context",
  "drivers": ["3-5 short sentences (<=25 words each) on what moved or matters"],
  "risks": ["1-3 short sentences on risks or things to watch next"],
  "watchlist_notes": [ { "ticker": "BDO", "note": "<=20 words" } ],
  "news_tags": [ { "id": 1, "sentiment": "positive|neutral|negative", "score": number, "theme": "macro|rates|fx|earnings|corporate|policy|global|other", "tickers": ["BDO"], "one_line": "<=20 word takeaway" } ],
  "top_news_ids": [1, 2, 3]
}
Rules:
- Include a news_tags entry for EVERY numbered news item.
- top_news_ids: up to 5 most market-relevant item ids, most important first.
- tickers: PSE codes without suffix (e.g. "BDO", not "BDO.PS"), only when the item is clearly about that company.
- watchlist_notes: only for watchlist tickers with a notable move (>=1.5% or unusual volume) or relevant news.
- Cite figures only if they appear in the price data above.`;

return [{ json: {
  is_trading_day,
  skip_reason,
  today,
  trade_date: psei?.trade_date ?? null,
  model: cfg.model || 'gemini-3.6-flash',
  news,
  // Gemini generateContent body (model goes in the URL, not the body)
  requestBody: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: {
      temperature: 0.2,
      maxOutputTokens: 8192,
      responseMimeType: 'application/json',
    },
  },
}}];

// Validates the LLM JSON, joins it back to real headlines/URLs, and builds the Telegram message + DB rows.
const ctx = $('Build LLM Input').first().json;
const prices = $('Parse Market Data').all().map(i => i.json);
const resp = $input.first().json;

const cand = resp.candidates?.[0];
if (!cand) {
  throw new Error('Gemini returned no candidates: ' + JSON.stringify(resp.promptFeedback || resp).slice(0, 300));
}
const raw = (cand.content?.parts || [])
  .filter(p => typeof p.text === 'string' && !p.thought)
  .map(p => p.text).join('').trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Gemini response was not valid JSON (finishReason: ${cand.finishReason}): ${e.message}`);
}

const clamp = (x) => Math.max(-1, Math.min(1, Number(x) || 0));
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = (s) => esc(s).replace(/"/g, '&quot;');
const strArr = (a, n) => (Array.isArray(a) ? a : []).slice(0, n).map(x => String(x));

const LABELS = ['bullish', 'neutral', 'bearish'];
const ms = parsed.market_sentiment || {};
const label = LABELS.includes(ms.label) ? ms.label : 'neutral';
const score = +clamp(ms.score).toFixed(3);

// ---- news rows (real titles/URLs come from the feeds, never from the LLM) ----
const SENT = ['positive', 'neutral', 'negative'];
const tags = new Map((Array.isArray(parsed.news_tags) ? parsed.news_tags : []).map(t => [Number(t.id), t]));
const news_rows = ctx.news.map(n => {
  const t = tags.get(n.id) || {};
  return {
    brief_date: ctx.trade_date,
    source: n.source,
    title: n.title,
    url: n.url,
    published_at: n.published_at,
    summary: t.one_line ?? null,
    sentiment: SENT.includes(t.sentiment) ? t.sentiment : null,
    sentiment_score: t.score == null ? null : +clamp(t.score).toFixed(3),
    theme: t.theme ?? null,
    tickers: Array.isArray(t.tickers) ? t.tickers.map(x => String(x).toUpperCase().replace(/\.PS$/, '')) : [],
  };
});

// ---- message helpers ----
const sgn = (x, d = 2) => x == null ? 'n/a' : `${x > 0 ? '+' : ''}${Number(x).toFixed(d)}%`;
const num = (x, d = 2) => x == null ? 'n/a' : Number(x).toLocaleString('en-US', { maximumFractionDigits: d });
const arrow = (x) => x > 0 ? '▲' : x < 0 ? '▼' : '■';
const tk = (p) => p.symbol.replace(/\.PS$/, '');
const moodEmoji = { bullish: '🟢', neutral: '🟡', bearish: '🔴' }[label];
const sentEmoji = { positive: '🟢', neutral: '⚪', negative: '🔴' };

const psei = prices.find(p => p.kind === 'index');
const stocks = prices.filter(p => p.kind === 'stock' && p.change_pct != null);
const sorted = [...stocks].sort((a, b) => b.change_pct - a.change_pct);
const gainers = sorted.filter(p => p.change_pct > 0).slice(0, 3);
const losers = [...sorted].reverse().filter(p => p.change_pct < 0).slice(0, 3);
const up = stocks.filter(p => p.change_pct > 0).length;
const down = stocks.filter(p => p.change_pct < 0).length;
const macro = prices.filter(p => p.kind === 'macro');

const dateLabel = new Date(ctx.trade_date + 'T00:00:00Z')
  .toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' });

const idIndex = new Map(ctx.news.map(n => [n.id, n]));
let topIds = (Array.isArray(parsed.top_news_ids) ? parsed.top_news_ids : []).map(Number).filter(id => idIndex.has(id));
if (!topIds.length) topIds = ctx.news.slice(0, 5).map(n => n.id);
topIds = [...new Set(topIds)].slice(0, 5);

const drivers = strArr(parsed.drivers, 5);
const risks = strArr(parsed.risks, 3);

function build(nHeadlines) {
  const L = [];
  L.push(`📊 <b>PSE Daily Brief</b> · ${esc(dateLabel)}`);
  if (psei) L.push(`<b>PSEi</b> ${num(psei.close)} (${arrow(psei.change_pct)} ${sgn(psei.change_pct)})` + (psei.ret_5d != null ? ` · 5d ${sgn(psei.ret_5d)}` : '') + (psei.ret_20d != null ? ` · 20d ${sgn(psei.ret_20d)}` : ''));
  if (stocks.length) L.push(`Watchlist breadth: ${up}▲ / ${down}▼`);
  L.push('');
  L.push(`${moodEmoji} <b>Sentiment: ${label}</b> (${score > 0 ? '+' : ''}${score.toFixed(2)})`);
  if (parsed.summary) L.push(esc(parsed.summary));

  if (gainers.length || losers.length) {
    L.push('');
    L.push('<b>Movers</b>');
    if (gainers.length) L.push('▲ ' + gainers.map(p => `${tk(p)} ${sgn(p.change_pct)}`).join(' · '));
    if (losers.length) L.push('▼ ' + losers.map(p => `${tk(p)} ${sgn(p.change_pct)}`).join(' · '));
  }
  if (macro.length) {
    L.push('');
    L.push('<b>Macro</b>');
    L.push(macro.map(p => `${esc(p.name)} ${num(p.close)} (${sgn(p.change_pct)})`).join(' · '));
  }
  if (drivers.length) {
    L.push('');
    L.push('<b>Drivers</b>');
    drivers.forEach(d => L.push('• ' + esc(d)));
  }
  if (nHeadlines > 0) {
    L.push('');
    L.push('<b>Headlines</b>');
    topIds.slice(0, nHeadlines).forEach(id => {
      const n = idIndex.get(id);
      const t = tags.get(id) || {};
      L.push(`${sentEmoji[t.sentiment] || '⚪'} <a href="${escAttr(n.url)}">${esc(n.title)}</a> <i>(${esc(n.source)})</i>`);
    });
  }
  if (risks.length) {
    L.push('');
    L.push('<b>Watch</b>');
    risks.forEach(r => L.push('• ' + esc(r)));
  }
  L.push('');
  L.push('<i>Automated summary from public data. Not investment advice.</i>');
  return L.join('\n');
}

let n = topIds.length;
let text = build(n);
while (text.length > 4000 && n > 0) text = build(--n);
if (text.length > 4000) text = text.slice(0, 3990) + '…';

return [{ json: {
  brief_date: ctx.trade_date,
  sentiment_label: label,
  sentiment_score: score,
  rationale: String(ms.rationale || ''),
  summary: String(parsed.summary || ''),
  drivers,
  risks,
  watchlist_notes: (Array.isArray(parsed.watchlist_notes) ? parsed.watchlist_notes : []).slice(0, 10)
    .map(w => ({ ticker: String(w.ticker || '').toUpperCase().replace(/\.PS$/, ''), note: String(w.note || '') })),
  model: resp.modelVersion || ctx.model,   // the model that actually answered (primary or fallback)
  telegram_text: text,
  news_rows,
}}];

// Strip news_rows so the remaining fields match the daily_briefs columns exactly.
const { news_rows, ...row } = $input.first().json;
return [{ json: row }];
